import { CASES } from './cases.js';
import { LORE, PRELUDE } from './lore.js';

// Public browser interface. Authentication, authorization, answer validation,
// time locks and the final reveal are all enforced by Supabase PostgreSQL RPCs.
const cfg = window.OHANA_CONFIG || {};
const root = document.getElementById('app');
let client = null, snapshot = null, busy = false, selectedRole = 'player';
let flash = '', flashKind = 'good';
let ambientSound = false;
let signalFrequency = 60;
let clockCorrection = 0;
let cipherShift = 0;
let cipherPhrase = 'TRANSMISSION';
let lastVaultData = null, lastSecretData = null;
const bonusChecked = new Set();
try { CASES.forEach(d=> {if(localStorage.getItem('ohana626-blackbox-'+d.id)==='1')bonusChecked.add(d.id);}); } catch {}
const loreOf = n=>LORE[n-1] || LORE[0];
const cachedHints = new Map();
const enhanced = new Set();
const FINALE = Date.parse('2026-12-14T13:00:00Z');
const areas = [
  ['dispatch','Dispatch','radio-tower'],
  ['surveillance','Surveillance','cctv'],
  ['laboratory','Laboratory','flask'],
  ['registry','Personnel Registry','id-card']
];
const esc = v => String(v ?? '').replace(/[&<>"']/g, s => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
const stamp = v => v ? new Date(v).toLocaleString() : 'Not recorded';
const profile = () => snapshot?.profile || {solved_days:[], gate_steps:{},fragments:{}, failed_attempts:{},hint_tiers:{},hints_used:0,time_seconds:0,vault_unlocked:false};
const solved = d => (profile().solved_days||[]).includes(d);
const gateStage = d => solved(d) ? 3 : Number((profile().gate_steps||{})['d'+d] || 0);
const currentRoute = () => decodeURIComponent((location.hash || '#/dashboard').slice(1));
const unlockAt = n => Date.UTC(2026,n===1?10:11,n===1?30:n-1,13);
const canPlay = n => solved(n) || (!!snapshot?.test_mode || Date.parse(snapshot?.server_time||'')>=unlockAt(n)) && (n===1 || solved(n-1));
const activeCase = () => CASES.find(d=>canPlay(d.id)&&!solved(d.id)) || CASES.filter(d=>canPlay(d.id)).at(-1) || CASES[0];
const dayCase = n => CASES.find(x=>x.id===Number(n));
const roomUrl = (section,n) => `#/facility/${section}/${n}`;
const doorUrl = n => `#/door/${n}`;
const fmtDay = n => String(n).padStart(2,'0');
const setFlash = (s,k='good') => { flash=s; flashKind=k; };
const banner = () => { if(!flash) return ''; const x=`<div role="status" class="alert ${flashKind==='bad'?'bad':'good'}">${esc(flash)}</div>`;flash='';return x; };
const safeUrl = v => {try {const u=new URL(v);return /^(https?:)$/.test(u.protocol)?esc(u.href):'';}catch{return '';}};
const metric = (label,val) => `<div class="metric"><div class="eyebrow">${esc(label)}</div><div class="metric-value">${esc(val)}</div></div>`;

async function rpc(method,parameters={}){
  if(!client) throw new Error('Edit config.js with your public Supabase URL and publishable key.');
  const {data,error}=await client.rpc(method,parameters);
  if(error)throw new Error(error.message||'Network request failed.');
  return data;
}
async function refresh(shouldRender=true){snapshot=await rpc('ohana_state');if(shouldRender)render();}
async function activity(path){if(snapshot?.role==='player')try{await rpc('ohana_track',{p_page:path});}catch(e){console.warn(e.message);}}
const navigate=path=>{location.hash='#'+path;render();};
async function signOut(){await client.auth.signOut();snapshot=null;location.hash='';render();}

function emblem(size='small'){return `<img src="emblem.svg" class="sigil ${size}" alt="Federation insignia">`;}
function orbitGraphic(){return `<div class="orbit-graphic" aria-hidden="true"><div class="orbit orbit1"></div><div class="orbit orbit2"></div><div class="orbit orbit3"></div><div class="orbit-core">${emblem('orbit-mark')}</div><span class="orbit-ping ping1"></span><span class="orbit-ping ping2"></span><span class="orbit-ping ping3"></span></div>`;}
function miniWave(n=1){const data=Array.from({length:48},(_,i)=>Math.round(20+22*Math.sin((i+n*7)*.7)+8*Math.sin((i+n)*2.2)));return `<div class="wave" aria-hidden="true">${data.map(v=>`<span style="height:${Math.max(4,v)}px"></span>`).join('')}</div>`;}
function loginView(error=''){
 root.innerHTML=`<div class="entry-sky"><div class="entry-nebula"></div><div class="grain"></div></div><main class="entry-grid"><section class="entry-poster"><div class="entry-eyebrow"><span class="status-dot"></span> FEDERATION NETWORK / ACTIVE TRANSMISSION / 626-A</div>${emblem('poster-mark')}<p class="chapter-tag">A STORY HIDDEN INSIDE A MYSTERY</p><h1 class="entry-display">EVERY<br>CLUE<br><em>LEADS HOME.</em></h1><p class="entry-deck">Fifteen nights. Forty-five locks. One missing artifact. And a truth that someone has gone to extraordinary lengths to hide.</p><div class="poster-meta"><span>CASE WINDOW · NOV 30—DEC 14</span><span>CLASSIFICATION · IRREPLACEABLE</span></div></section><section class="login-panel"><div class="login-topline"><span>PROJECT: OHANA—626</span><span class="live-led">● SECURE CHANNEL</span></div><div class="login-sigil">${emblem('large')}</div><p class="overline center">GALACTIC FEDERATION / IDENTITY VERIFICATION</p><h2>Access the <em>archive.</em></h2><p class="quiet">Unauthorized transmissions have been detected. Present your agent credentials to continue.</p>
 ${error?`<div class="alert bad" role="alert">${esc(error)}</div>`:''}${banner()}<form id="loginForm"><div class="role-grid"><label class="role-box"><input type="radio" name="role" value="player" ${selectedRole==='player'?'checked':''}><span class="role-number">01 / FIELD AGENT</span><strong>BUNNY</strong><small>BELLA · INVESTIGATOR</small></label><label class="role-box"><input type="radio" name="role" value="admin" ${selectedRole==='admin'?'checked':''}><span class="role-number">02 / COMMAND</span><strong>WYATT</strong><small>HANDLER · ADMIN</small></label></div><label for="loginPassword" class="overline">CLEARANCE PASSWORD</label><input id="loginPassword" class="field" name="password" type="password" minlength="6" autocomplete="current-password" required placeholder="Enter password"><button class="button primary wide" type="submit">ESTABLISH SECURE CONNECTION <span>↗</span></button></form><div class="login-bottom"><span>NO EMAIL NEEDED ON THIS WEBSITE</span><span>END-TO-END FIELD SESSION</span></div></section></main>`;
}
function navItems(id){return snapshot.role==='admin' ? [['/admin','◈','Command Center']] : [
 ['/dashboard','⌂','Command Deck'],['/prelude','✉','Incident Prelude'],['/atlas','⬡','Facility Atlas'],['/reports','▤','Case Files'],['/doors','◧','Security Doors'],
 ['/dossier/'+id,'◉','Mission Briefing'],['/facility/dispatch/'+id,'⌁','Dispatch'],['/facility/surveillance/'+id,'▦','Surveillance'],
 ['/facility/laboratory/'+id,'⚗','Laboratory'],['/facility/registry/'+id,'♙','Personnel'],
 ['/board','⤳','Evidence Board'],['/archive','▥','Recovered Archive'],['/suspects','♧','Suspect Registry'],
 ['/blackbox','◷','Black Box Decoder'],['/field-kit','⊞','Forensic Tools'],['/transmissions','⌁','Transmissions'],['/vault','✶','The Vault'] ];}
function shell(content,subtitle='FIELD TERMINAL'){
 const id=activeCase().id, route=currentRoute(), nav=navItems(id);
 root.innerHTML=`<div class="shell"><div class="global-noise" aria-hidden="true"></div><aside class="side-rail" aria-label="Facility sectors"><a class="rail-logo" href="#/dashboard" aria-label="Home">${emblem('small')}</a><div class="rail-brand">PROJECT <strong>OHANA<span>626</span></strong><small>F E D E R A T I O N</small></div><p class="rail-caption">${snapshot.role==='admin'?'COMMAND AUTHORIZATION':'SECURITY LEVEL / SIX'}</p><nav class="rail-links">${nav.map(([link,icon,label])=>`<a href="#${link}" class="rail-link ${route===link?'current':''}"><span class="rail-icon">${esc(icon)}</span><span>${esc(label)}</span></a>`).join('')}</nav><div class="rail-foot"><span class="status-dot"></span><span>NETWORK CONNECTED</span><small>EST. 2026</small></div></aside><div class="console"><header class="mast"><div class="mast-path"><span class="mast-mark">✦</span><span>THE GALACTIC FEDERATION</span><i>/</i><span>${esc(subtitle)}</span></div><div class="mast-right"><span class="clearance">${snapshot.role==='admin'?'ADMIN · WYATT':'FIELD · BUNNY'}</span><button class="sound-btn" data-action="sound" title="Toggle interface sounds" aria-label="Toggle interface sounds">${ambientSound?'♪ ON':'♪ OFF'}</button><button class="text-button" data-action="logout">LOG OUT ↗</button></div></header><nav class="nav" aria-label="Quick navigation">${nav.map(([link,icon,label])=>`<a href="#${link}" class="${route===link?'on':''}"><span>${esc(icon)}</span>${esc(label)}</a>`).join('')}</nav><div class="topline"><span><span class="status-dot"></span> ${esc(subtitle)} <span class="slash">/</span> FILE 626-A</span><span class="topline-date" id="utcClock">UNIVERSAL SIGNAL ACTIVE</span></div>${banner()}<main id="pageContent">${content}</main><footer>GALACTIC FEDERATION · FICTIONAL GAME NETWORK <span>✧</span> CRAFTED WITH LOVE BY WYATT FOR BELLA · 2026</footer></div></div>`;
 document.querySelectorAll('[data-qr]').forEach(el=>{if(!window.QRCode){el.textContent='Open the signal link below.';return;}try{new window.QRCode(el,{text:el.dataset.qr,width:124,height:124,correctLevel:window.QRCode.CorrectLevel.M});}catch{el.textContent='Open signal link.';}});
}
function gateMeter(n){let stage=gateStage(n);return `<div class="bolts mini">${[1,2,3].map(g=>`<span class="bolt ${stage>=g?'unsealed':''}">${stage>=g?'✓':'▣'} ${g}</span>`).join('')}</div>`;}
function caseTile(d){const open=canPlay(d.id),done=solved(d.id),stage=gateStage(d.id);
 return `<a class="case-tile ${open?'':'sealed'}" href="${doorUrl(d.id)}"><span class="eyebrow">DAY ${fmtDay(d.id)} • ${esc(d.date)}</span><h3>${esc(d.title)}</h3><p class="quiet small">${esc(d.tag)}</p><div class="case-foot"><span class="status ${done?'done':open?'live':''}">${done?'RETRIEVED':open?`DOOR ${stage}/3`:'DATE LOCKED'}</span>${gateMeter(d.id)}</div></a>`;}
function currentBrief(d){return `<div class="case-heading"><span class="eyebrow">CASE ${fmtDay(d.id)} / ${esc(d.tag)}</span><h1>${esc(d.title)}</h1><p>${esc(d.story)}</p><div class="chiprow"><span class="chip">${esc(d.date)}, 2026</span><span class="chip">${gateStage(d.id)} / 3 BOLTS</span>${solved(d.id)?'<span class="chip green">FILE RECOVERED</span>':''}</div></div>`;}
function crossLinks(d,omit=''){return `<div class="room-links">${areas.filter(([s])=>s!==omit).map(([s,name])=>`<a href="${roomUrl(s,d.id)}" class="sub-link">↗ ${esc(name)}</a>`).join('')}<a class="sub-link prominent" href="${doorUrl(d.id)}">↗ SECURITY DOOR</a></div>`;}
function roomNotebook(day){let text='';try{text=localStorage.getItem('ohana626-notes-'+day)||'';}catch{}
 return `<aside class="card notebook"><div class="eyebrow">YOUR PRIVATE CASE NOTEBOOK</div><p class="quiet small">Copy observations here while moving between rooms. Notes stay on this device, not Supabase.</p><textarea class="field" data-note="${day}" rows="4" maxlength="5000" placeholder="Camera offsets, suspected seals, calculations...">${esc(text)}</textarea><p class="quiet micro" data-note-status>Saved locally when you type.</p></aside>`;}
function locked(n){const d=dayCase(n);const date=new Date(unlockAt(n));return `<section class="card"><div class="huge-icon">◈</div><h1>SECTOR SEALED</h1><p>Investigation ${fmtDay(n)}${d?' — '+esc(d.title):''} is unavailable until ${esc(date.toLocaleString('en-US',{dateStyle:'medium',timeStyle:'short',timeZone:'America/New_York'}))} Eastern, after the prior day is solved.</p><a href="#/reports" class="button secondary">RETURN TO CASE INDEX</a></section>`;}
function table(headers,rows){return `<div class="table-wrap"><table class="records"><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function home(){const p=profile(),done=p.solved_days?.length||0,next=activeCase(),rem=Math.max(0,Date.parse('2026-12-14T13:00:00Z')-Date.parse(snapshot.server_time||new Date().toISOString()));
 const dd=Math.floor(rem/86400000),hh=Math.floor((rem%86400000)/3600000);
 shell(`<section class="hero hero-cinema"><div class="hero-inner"><div class="eyebrow"><span class="status-dot"></span> OPERATION 626-A <span class="dash-sep">/</span> CLASSIFIED CASE</div><div class="hero-kicker">THE GALACTIC FEDERATION PRESENTS</div><h1>THE ARTIFACT<br>IS <em>MISSING.</em></h1><p>What begins as a galactic theft unravels across hidden departments, fractured memories, and fifteen impossible security doors. Agent Bunny, your investigation starts here.</p><div class="hero-actions"><a class="button primary" href="${doorUrl(next.id)}">CONTINUE THE INVESTIGATION <span>↗</span></a><a class="button ghost" href="#/atlas">EXPLORE THE FACILITY</a></div><div class="hero-foot"><span>◉ LIVE CASE · ${fmtDay(next.id)} / 15</span><span>△ INVESTIGATION SECTOR: ${esc(loreOf(next.id).sector)}</span></div></div><div class="hero-graphics">${orbitGraphic()}</div></section>
 <div class="section-label"><span>01 / MISSION TELEMETRY</span><span>FEDERATION SYSTEMS ONLINE</span></div><div class="metrics show-metrics">${metric('EVIDENCE RECOVERED',`${done} / 15`)}${metric('CURRENT ACCESS',`${gateStage(next.id)} / 3`)}${metric('UNTIL FINALE',`${dd}D ${hh}H`)}${metric('HINTS UTILIZED',p.hints_used||0)}</div>
 ${snapshot.test_mode?'<div class="alert warning">SIMULATION / TEST MODE ACTIVE — DATE RESTRICTIONS TEMPORARILY BYPASSED.</div>':''}${notices()}
 <div class="mission-feature"><section class="feature-case"><div class="section-label"><span>02 / PRIORITY INVESTIGATION</span><span>${esc(loreOf(next.id).code)}</span></div><div class="feature-case-inner"><span class="case-chip">CASE FILE ${fmtDay(next.id)} · ${esc(next.date)}</span><h2>${esc(next.title)}</h2><p>${esc(loreOf(next.id).brief)}</p><div class="mission-stages"><span>01 AUTHENTICATE</span><span>02 DECRYPT</span><span>03 BREACH</span></div><a href="#/dossier/${next.id}" class="text-cta">READ THE MISSION DOSSIER <span>↗</span></a><a href="${doorUrl(next.id)}" class="text-cta">ACCESS SECURITY DOOR <span>↗</span></a></div></section><section class="facility-mini"><div class="section-label"><span>03 / STATION BLUEPRINT</span><span>4 SECTORS</span></div><div class="holo-map">${facilityMap(next.id)}</div><a href="#/atlas" class="text-cta">OPEN INTERACTIVE ATLAS ↗</a></section></div>
 <div class="section-label"><span>04 / CURRENT CASE FILES</span><a href="#/reports">VIEW ALL 15 CASES ↗</a></div><div class="case-grid cinematic-cases">${CASES.slice(Math.max(0,next.id-2),Math.min(15,next.id+3)).map(caseTile).join('')}</div>
 <section class="endnote"><span>✧</span><p><em>“Some things are worth the whole universe.”</em></p><small>UNSIGNED TRANSMISSION / ORIGIN UNKNOWN</small></section>`,'FIELD COMMAND DECK');}
function facilityMap(n){const links=[['dispatch','DISPATCH',85,82],['surveillance','SURVEILLANCE',280,58],['laboratory','LABORATORY',275,180],['registry','PERSONNEL',85,195]];
return `<svg viewBox="0 0 370 260" class="map-svg" role="img" aria-label="Interactive facility map linking Dispatch, Surveillance, Laboratory and Personnel Registry"><defs><pattern id="grid" width="18" height="18" patternUnits="userSpaceOnUse"><path d="M18 0H0V18" stroke="#317e99" stroke-opacity=".19" fill="none"/></pattern></defs><rect width="370" height="260" fill="url(#grid)"/><g stroke="#4ddcf4" stroke-opacity=".4" stroke-width="2" fill="none"><path d="M85 82 L280 58 275 180 85 195 Z" stroke-dasharray="5 7"/><path d="M85 82 275 180M280 58 85 195" stroke-opacity=".15"/></g><circle cx="184" cy="127" r="49" fill="#0a3343" stroke="#65d5ed" stroke-opacity=".4" stroke-width="2"/><circle cx="184" cy="127" r="38" fill="none" stroke="#65d5ed" stroke-opacity=".2" stroke-dasharray="2 6"/><text x="184" y="122" text-anchor="middle" fill="#bdeeff" font-size="12" font-weight="bold">626-A</text><text x="184" y="138" text-anchor="middle" fill="#85b5c8" font-size="8" letter-spacing="2">COMMAND</text>${links.map(([path,label,x,y],i)=>`<a href="${roomUrl(path,n)}"><circle cx="${x}" cy="${y}" r="23" fill="#092735" stroke="#63d8eb" stroke-width="2"/><circle cx="${x}" cy="${y}" r="6" fill="#a4f5fc"/><text x="${x}" y="${y+37}" fill="#c6eefa" font-size="9" text-anchor="middle" letter-spacing="1">${label}</text></a>`).join('')}</svg>`;}
function notices(){const notes=snapshot?.notes||[];return notes.length?`<section class="card"><h2>Incoming handler transmissions</h2>${notes.slice(0,5).map(n=>`<div class="transmission"><div class="eyebrow">${esc(stamp(n.created_at))}</div><p>${esc(n.message)}</p></div>`).join('')}</section>`:'';}
function reports(){shell(`<div class="case-heading"><div class="eyebrow">INVESTIGATION REGISTER</div><h1>15 doors. 45 independent locks.</h1><p>Each mission has evidence spread between Dispatch, Surveillance, Laboratory and Personnel Registry. The Security Door page only tells you what to find — it does not hold the evidence.</p></div><div class="case-grid">${CASES.map(caseTile).join('')}</div>`,'CASE INDEX');}
function allDoors(){const next=activeCase();shell(`<div class="case-heading"><div class="eyebrow">DOOR DIRECTORY</div><h1>Sealed Corridor</h1><p>Every day reveals one new chamber. The chamber opens only after three validated clearance codes have been entered in sequence.</p></div><a class="button primary" href="${doorUrl(next.id)}">OPEN CURRENT DOOR →</a><div class="case-grid spaced">${CASES.map(caseTile).join('')}</div>`,'DOOR NETWORK');}
function facility(section,n){const d=dayCase(n);if(!d){shell('<div class="alert bad">Unknown case number.</div>');return;}if(!canPlay(n)){shell(locked(n));return;}
 const sec=areas.find(([name])=>name===section);if(!sec){shell('<div class="alert bad">Unknown department.</div>');return;}
 let payload='';
 if(section==='dispatch'){
  const x=d.dispatch;payload=`<p>${esc(x.intro)}</p><div class="small-label">INTERCEPTED TRANSMISSIONS — SCRAMBLED ORDER</div>${table(['TX ID','CLAIMED CALLSIGN','CLEARANCE','SECURITY SEAL'],x.rows.map(r=>[r.id,r.caller,r.level,r.seal]))}
  <div class="notice-box"><strong>Attached authorization memo:</strong> The approved specimen lot for this incident is <span class="mono strong">${esc(x.batch)}</span>. Unapproved specimens are decoys.</div>`;
 }else if(section==='registry'){
  const x=d.registry;payload=`<p>${esc(x.intro)}</p><div class="record-grid"><div class="record"><small>VERIFIED IDENTITY</small><strong>${esc(x.caller)}</strong></div><div class="record"><small>REQUIRED CLEARANCE</small><strong>LEVEL ${x.clearance}</strong></div><div class="record"><small>SEAL ORIENTATION</small><strong>${x.mirror?'MIRROR / REVERSE':'NORMAL / FORWARD'}</strong></div><div class="record"><small>CAMERA REEL ORDER</small><strong>${x.reel}</strong></div></div>
  <h3>Maintenance route for the power conduit</h3><div class="route-strip">${x.order.map((sector,i)=>`<span>${i+1}. ${esc(sector)}</span>`).join('<i>➜</i>')}</div><div class="notice-box">Margin note: ${esc(x.note)} ${d.hidden?`<a href="#${d.hidden}">Investigate the handwritten route</a>`:''}</div>`;
 }else if(section==='surveillance'){
  const x=d.surveillance;payload=`<p>${esc(x.intro)}</p><div class="notice-box"><strong>Camera enhancement:</strong> the glyph column is hidden in the raw feed. Tap ENHANCE FOOTAGE to reveal it. This action is part of the investigation.</div><button class="button secondary" data-action="enhance" data-day="${n}">${enhanced.has(n)?'RETURN TO RAW FOOTAGE':'▣ ENHANCE FOOTAGE'}</button><div class="spaced">${table(['CAMERA','RECORDED MINUTE','SPECTRUM','ENHANCED GLYPH'],x.frames.map(r=>[r.camera,`16:${String(r.minute).padStart(2,'0')}`,r.channel,enhanced.has(n)?r.glyph:'▧▧']))}</div><p class="quiet small">Do not assume the earliest displayed minute is the earliest real event. Laboratory records separate offsets for each camera.</p>`;
 }else if(section==='laboratory'){
  const x=d.laboratory;payload=`<p>${esc(x.intro)}</p><div class="notice-box"><strong>QUARANTINED SPECTRUM:</strong> <span class="mono">${esc(x.blocked)}</span> · <strong>VERIFIED SPECTRUM:</strong> <span class="mono">${esc(x.valid)}</span></div>
 <details class="file-folder"><summary>OPEN LAB FILE 1 — CAMERA CLOCK CALIBRATIONS</summary><p class="quiet small">To correct a camera timestamp, add its offset in minutes to the recorded time from Surveillance. Some offsets are negative.</p>${table(['CAMERA','TIME CORRECTION'],x.calibration.map(r=>[r.camera,(r.offset>0?'+':'')+r.offset+' min']))}</details>
 <details class="file-folder"><summary>OPEN LAB FILE 2 — SPECIMEN LEDGER</summary><p class="quiet small">Only the authorized batch printed in Dispatch is genuine. A and B are instrument readings, not letters.</p>${table(['SECTOR','BATCH','READING A','READING B'],x.samples.map(r=>[r.sector,r.batch,r.a,r.b]))}</details>`;
 }
 const side=d.addon?.room===section ? `<section class="card side-exhibit"><div class="eyebrow">UNLISTED SIDE EXHIBIT / ${esc(section.toUpperCase())}</div><h2>${esc(d.addon.title)}</h2><p>${esc(d.addon.text)}</p><div class="artifact-lines">${d.addon.lines.map(line=>`<div>${esc(line)}</div>`).join('')}</div><p class="notice-box"><strong>Supplemental door marker:</strong> ${esc(d.addon.instruction)}</p></section>` : '';
 shell(`${currentBrief(d)}<div class="room-layout"><div><section class="card room-card"><div class="eyebrow">DEPARTMENT / ${esc(sec[1].toUpperCase())}</div><h2>${esc(d[section].title)}</h2>${payload}</section>${side}
 <section class="card"><div class="eyebrow">MOVE THROUGH THE FACILITY</div><h3>Cross-reference another department</h3>${crossLinks(d,section)}</section></div><div>${roomNotebook(n)}<section class="card"><div class="eyebrow">EXPERIMENT 626 SCRATCHED THIS NOTE</div><p class="alien">“${esc(d.message)}”</p></section></div></div>`,sec[1].toUpperCase());
}
function door(n){const d=dayCase(n);if(!d){shell('<div class="alert bad">Unknown door.</div>');return;}if(!canPlay(n)){shell(locked(n));return;}
 const st=gateStage(n),done=solved(n);const fail=Number((profile().failed_attempts||{})['d'+n]||0);const hintLevel=Number((profile().hint_tiers||{})['d'+n]||0);
 const missionSignal = location.origin+location.pathname+roomUrl('surveillance',n);
 shell(`${currentBrief(d)}<div class="door-layout"><div>
 <section class="door-hero ${done?'door-open':''}"><div class="door-frame"><div class="door-emblem">${done?'✦':'◈'}</div><div class="eyebrow">${done?'ACCESS GRANTED':'FEDERATION SECURITY LOCK'}</div><h2>${done?'THE DOOR IS OPEN':'THREE-BOLT AUTHENTICATION'}</h2><div class="bolts">${[1,2,3].map(g=>`<span class="bolt ${st>=g?'unsealed':''}">${st>=g?'✓':'▣'} BOLT ${g}</span>`).join('')}</div><p class="quiet">${done?'The recovered file has been archived. One more step toward the final vault.':'Each bolt needs evidence from at least two other pages. The door never tells you the answer.'}</p></div></section>
 ${d.doors.map((lock,i)=>{const g=i+1,passed=st>=g,available=!done&&st===g-1;return `<section class="card lock-card ${available?'lock-active':''}"><div class="lock-top"><span class="lock-index">0${g}</span><div><div class="eyebrow">${passed?'AUTHORIZATION CONFIRMED':available?'AWAITING EVIDENCE':'AWAITING PREVIOUS BOLT'}</div><h3>${esc(lock.title)}</h3></div><span class="lock-icon">${passed?'✓':available?'◌':'⬡'}</span></div><p>${esc(lock.prompt)}</p><div class="sources">${lock.sources.map(s=>s==='board'?'<a href="#/board">↗ Evidence Board</a>':s==='classified'?'<a href="#/classified">↗ Classified Annex</a>':s==='ohana'?'<a href="#/archive/ohana">↗ OHANA Annex</a>':`<a href="${roomUrl(s,n)}">↗ ${esc(areas.find(([k])=>k===s)?.[1]||s)}</a>`).join('')}</div>
 ${passed?'<div class="alert good">BOLT RELEASED • AUTHENTICATED</div>':available?`<form id="doorForm" data-day="${n}" data-gate="${g}"><label for="doorGuess">${esc(lock.format)} — enter final code</label><div class="entry-row"><input class="field" id="doorGuess" name="guess" type="text" maxlength="75" autocomplete="off" autocapitalize="characters" required placeholder="Enter clearance code"><button class="button primary" type="submit">TRY BOLT ${g}</button></div></form>`:'<div class="notice-box">Unlock the previous bolt before this panel accepts input.</div>'}</section>`}).join('')}
 ${done?`<section class="card recovered"><div class="eyebrow">E-${fmtDay(n)} / RECOVERED</div><h2>${esc(d.evidenceTitle)}</h2><p>${esc(d.evidence)}</p><p>Meta evidence stamp: <span class="meta-fragment">${esc((profile().fragments||{})['d'+n]||'')}</span></p><a href="#/archive" class="button secondary">VIEW ARCHIVE</a> ${n<15?`<a class="button primary" href="${doorUrl(n+1)}">NEXT DAY →</a>`:'<a href="#/vault" class="button primary">FINAL VAULT →</a>'}</section>`:''}
 </div><div><section class="card sidepanel"><div class="eyebrow">FIELD AGENT TOOLKIT</div><h3>Browse the linked sectors</h3>${crossLinks(d)}<p class="quiet small spaced">Use your notes to keep offsets, stamps and possible combinations while moving between files.</p></section>
 ${roomNotebook(n)}<section class="card"><h3>Federation hint authorization</h3><p class="quiet small">Three hints per day. New hints are logged for Wyatt.</p><div class="hint-buttons">${[1,2,3].map(t=>`<button data-action="hint" data-day="${n}" data-tier="${t}" class="button secondary" ${t>hintLevel+1?'disabled':''}>${t<=hintLevel?'Review':'Unlock'} hint ${t}</button>`).join('')}</div><div class="hint-output">${cachedHints.get(n)||''}</div><p class="quiet micro">Failed attempts: ${fail} · Spaces and punctuation are ignored.</p></section>
 <section class="card"><div class="eyebrow">QR TRANSIT PASS ${fmtDay(n)}</div><p class="quiet small">This QR opens this case's Surveillance room. If you are playing on one phone, tap the normal link instead.</p><div class="qr" data-qr="${esc(missionSignal)}"></div><a href="${roomUrl('surveillance',n)}">Open linked camera feed →</a></section></div></div>`, 'SECURITY CORRIDOR');
}
function board(){const p=profile();shell(`<section class="case-heading"><div class="eyebrow">CONNECTED EVIDENCE</div><h1>The Investigation Board</h1><p>Something has been hiding in plain sight. Each opened door adds a single verified stamp. You can revisit every finished case.</p></section><section class="card"><h2>Recovered stamp sequence</h2><div class="meta-row">${CASES.map(d=>`<a href="${doorUrl(d.id)}" class="meta-card ${solved(d.id)?'acquired':''}"><small>${fmtDay(d.id)}</small><strong>${solved(d.id)?esc((p.fragments||{})['d'+d.id]||'?'):'?'}</strong></a>`).join('')}</div><p class="quiet small">Fourteen days may look random. The complete sequence becomes meaningful near the final vault.</p></section><section class="card"><h2>Connections under investigation</h2><div class="story-threads">${CASES.map(d=>`<a href="${doorUrl(d.id)}" class="thread ${solved(d.id)?'recovered':''}"><span class="eyebrow">E-${fmtDay(d.id)}</span><strong>${esc(d.title)}</strong><small>${solved(d.id)?esc(d.emotion):'CLASSIFIED / UNKNOWN'}</small></a>`).join('')}</div></section>`,'EVIDENCE BOARD');}
function archive(){const docs=CASES.filter(d=>solved(d.id));shell(`<section class="case-heading"><div class="eyebrow">ARCHIVE / RECOVERED MATERIAL</div><h1>The Evidence Archive</h1><p>Files appear here only after their three locks have been solved. Revisit earlier memories and stamps to spot the second investigation.</p></section><section class="card"><h2>Recovered files ${docs.length} / 15</h2>${docs.length?docs.map(d=>`<article class="archive-item"><span class="eyebrow">E-${fmtDay(d.id)} · ${esc(d.date)}</span><h3>${esc(d.evidenceTitle)}</h3><p>${esc(d.evidence)}</p><a href="${doorUrl(d.id)}">Return to this door →</a></article>`).join(''):'<p class="quiet">No complete recoveries yet. Begin with Security Door 01.</p>'}</section>${profile().vault_unlocked?'<section class="card"><h2>Unexpected record: ARCHIVED FILE 0914-B</h2><p>This record was hidden from the initial case inventory.</p><a class="button primary" href="#/0914-b">OPEN FILE →</a></section>':''}`,'EVIDENCE ARCHIVE');}
function annex(page){if(page==='/classified'&&!canPlay(7)){shell(locked(7));return;}if(page==='/archive/ohana'&&!canPlay(11)){shell(locked(11));return;}
 if(page==='/classified'){shell(`<section class="case-heading"><span class="eyebrow">UNLISTED FACILITY ROUTE / WOLF INDEX</span><h1>Classified Annex</h1><p>You found an annex omitted from the main navigation. The Registry margin was the only published route here.</p></section><section class="card"><div class="file-tag">TRACK VERIFICATION / 07</div><h2>The wolf-marker record</h2><p>Researcher note: five track markers were stamped. Only the red-circled marker survived ultraviolet scanning.</p><div class="mark-row"><span>U</span><span>S</span><span class="red-circle">R</span><span>N</span><span>V</span></div><p class="quiet">Official surviving TRACK MARKER is the red-circled character.</p><a href="${doorUrl(7)}" class="button secondary">RETURN TO DOOR 07</a></section>`,'HIDDEN ANNEX');return;}
 shell(`<section class="case-heading"><span class="eyebrow">UNLISTED FACILITY ROUTE / BOND INDEX</span><h1>OHANA Archive</h1><p>This archived classification file was not linked in the navigation. The Personnel Registry referenced it.</p></section><section class="card"><div class="file-tag">STATUS WORD / 11</div><h2>Unclassified relationship categories</h2><div class="notice-box">Chosen — stays — belonging.</div><p>When all three are present, the archival STATUS WORD is <strong>FAMILY</strong>.</p><p class="quiet">Door 11 asks for its first character, after the four keypad digits.</p><a href="${doorUrl(11)}" class="button secondary">RETURN TO DOOR 11</a></section>`,'HIDDEN ANNEX');}
function vault(){const p=profile(),count=(p.solved_days||[]).length;shell(`<section class="vault-stage ${p.vault_unlocked?'vault-ready':''}"><div class="vault-ring"><div class="vault-ring-inside">${emblem('vault-emblem')}</div></div><div class="vault-stage-copy"><span class="eyebrow">CHAMBER 0914 / FINAL AUTHORIZATION</span><h1>THE LAST<br><em>DOOR.</em></h1><p>Someone left fifteen fragments across fifteen investigations. Their pattern is the only key that can open this chamber. Everything you have recovered is here for a reason.</p><span class="vault-progress">${count} / 15 EVIDENCE STAMPS RECLAIMED</span></div></section>
 <section class="card vault-key"><div class="section-label"><span>SECOND INVESTIGATION / META KEY</span><span>REVIEW ALL EVIDENCE</span></div><h2>Assembler: the fifteen stamps</h2><p>Arrange the marks in day order, with no spaces. Only a completed mission can yield its stamp. The server verifies the final phrase.</p><div class="meta-row vault-stamps">${CASES.map(d=>`<a href="${doorUrl(d.id)}" class="meta-card ${solved(d.id)?'acquired':''}"><small>${fmtDay(d.id)}</small><strong>${solved(d.id)?esc((p.fragments||{})['d'+d.id]||'?'):'?'}</strong></a>`).join('')}</div>${count<15?`<div class="alert warning">${count}/15 investigations completed. The vault requires all fifteen doors.</div>`:''}${p.vault_unlocked?'<div class="alert good">RETRIEVAL STATUS / VAULT OPENED</div><button class="button primary" data-action="open-vault">REOPEN FINAL RECOVERY FILES ↗</button>':`<form id="vaultForm"><label for="meta">ENTER ASSEMBLED META PHRASE</label><div class="entry-row"><input id="meta" name="meta" class="field" type="text" required autocomplete="off" placeholder="FIFTEEN LETTERS"><button class="button primary" type="submit">OPEN THE VAULT ↗</button></div></form>`}</section><div id="vaultContent"></div>`,'FINAL RECOVERY VAULT');if(lastVaultData) vaultContents(lastVaultData);}
function vaultContents(c){const el=document.getElementById('vaultContent');if(!el||!c)return;lastVaultData=c;
 el.innerHTML=`<section class="reveal-header"><div class="reveal-stars" aria-hidden="true">✦ &nbsp; ✧ &nbsp; ✦ &nbsp; ✧ &nbsp; ✦</div><div class="eyebrow">GALACTIC FEDERATION / STATUS ${esc(c.status||'RECOVERED')}</div><h1>ARTIFACT<br><em>BELLA.</em></h1><div class="reveal-classification">CLASSIFICATION: ${esc(c.classification||'IRREPLACEABLE')} <span>✦</span> STATUS: ${esc(c.status||'RECOVERED')}</div><p>Not an object. Not a secret weapon. The answer was never a thing that could be stolen.</p></section><section class="card scrapbook-section"><div class="section-label"><span>EVERY RECOVERED MEMORY</span><span>CASE ARCHIVE / COMPLETE</span></div><h2>We were collecting moments.</h2><div class="scrapbook-grid">${(c.scrapbook||[]).map((v,i)=>`<article class="scrapbook-card"><div class="scrapbook-art scene-${i%5}"><span>${['✧','✦','☼','☾','♡'][i%5]}</span>${safeUrl(v.imageUrl)?`<img src="${safeUrl(v.imageUrl)}" alt="Memory: ${esc(v.title)}" loading="lazy">`:''}</div><div class="scrapbook-info"><small>RECOVERED ${String(i+1).padStart(2,'0')}</small><h3>${esc(v.title)}</h3><p>${esc(v.caption)}</p></div></article>`).join('')}</div></section><section class="letter-section"><span class="eyebrow">PERSONAL TRANSMISSION / UNSIGNED UNTIL NOW</span><h2>To Bella, from Wyatt.</h2><div class="letter-scroll"><p class="letter">${esc(c.letter)}</p></div><div class="letter-signature">WITH LOVE, WYATT ♡</div></section><section class="card final-gifts"><div class="section-label"><span>END OF MISSION / ADDITIONAL CONTENT</span><span>PERSONAL REWARDS</span></div><h2>One more surprise.</h2><div class="feature-grid">${[['videoUrl','▶','A message for you','OPEN VIDEO'],['playlistUrl','♫','Our soundtrack','OPEN PLAYLIST']].map(([k,icon,title,call])=>`<article class="feature-box"><span>${icon}</span><h3>${title}</h3><p>${safeUrl(c[k])?`<a href="${safeUrl(c[k])}" rel="noopener" target="_blank">${call} ↗</a>`:'Wyatt has not added this link yet.'}</p></article>`).join('')}<article class="feature-box"><span>♡</span><h3>Our next adventure</h3><p>${esc(c.dateReveal||'To be revealed by Wyatt.')}</p></article></div><a class="button ghost" href="#/0914-b">AN UNEXPECTED ARCHIVE FILE HAS APPEARED ↗</a></section>`;}
function secret(){if(!profile().vault_unlocked){shell('<section class="card"><h2>ARCHIVE ACCESS DENIED</h2><p>This file does not exist in your current clearance.</p></section>');return;}
 shell(`<section class="case-heading"><span class="eyebrow">POST-RECOVERY / UNLISTED FILE</span><h1>ARCHIVED FILE 0914-B</h1><p>One final classified message is still waiting. It has one password.</p></section><section class="card"><form id="secretForm"><label for="secretpass">Archive password</label><div class="entry-row"><input id="secretpass" name="secretpass" class="field" type="password" required autocomplete="off"><button class="button primary" type="submit">DECRYPT FILE</button></div></form><div id="secretContent"></div></section>`,'UNLISTED ARCHIVE');}
function secretContents(c){const el=document.getElementById('secretContent');if(!el||!c)return;lastSecretData=c;el.innerHTML=`<section class="true-ending"><div class="eyebrow">${esc(c.title)} / TRANSMISSION FROM WYATT</div><div class="true-ending-symbol">♡</div><h1>IT WAS<br><em>YOU.</em></h1><p class="ending-subtitle">THE INVESTIGATION WAS ALWAYS ABOUT BELLA.</p><div class="letter-scroll"><p class="letter">${esc(c.letter)}</p></div><div class="ending-lastline">NOT EVERY TREASURE IS SOMETHING YOU FIND.<br>SOMETIMES IT IS THE PERSON WHO BECOMES HOME.</div></section>`;}
function admin(){const p=snapshot?.profile,done=p?.solved_days?.length||0,fails=Object.values(p?.failed_attempts||{}).reduce((s,n)=>s+Number(n||0),0);
 shell(`<section class="hero admin-hero"><div class="eyebrow">AUTHORIZED COMMAND / AGENT WYATT</div><h1>Wyatt's Command Center</h1><p>Monitor Bella's real puzzle progress, per-page exploration, failed lock attempts and emergency messages. Refreshes about every 12 seconds.</p></section>${snapshot.test_mode?'<div class="alert warning">TEST MODE ON — future doors ignore dates. Reset Bella and disable Test Mode before launch.</div>':''}
 ${p?`<div class="metrics">${metric('Current day',`${Math.min(done+1,15)} / 15`)}${metric('Three-bolt progress',`${Number((p.gate_steps||{})['d'+Math.min(done+1,15)]||0)} / 3`)}${metric('Recovered evidence',`${done} / 15`)}${metric('Wrong lock tries',fails)}${metric('Hints used',p.hints_used||0)}${metric('Active time',Math.floor((p.time_seconds||0)/60)+' min')}</div><section class="card"><div class="section-label"><span>INVESTIGATION COMPLETION MAP</span><span>15 DAILY OPERATIONS</span></div><div class="admin-timeline">${CASES.map(c=>`<div class="admin-cell ${(p.solved_days||[]).includes(c.id)?'cleared':''}"><strong>${fmtDay(c.id)}</strong><span>${(p.solved_days||[]).includes(c.id)?'✓':String((p.gate_steps||{})['d'+c.id]||0)+'/3'}</span></div>`).join('')}</div></section><section class="card"><h2>Field agent telemetry</h2><div class="record-grid">${[['Last login',stamp(p.last_login)],['Last activity',stamp(p.last_seen)],['Current page',p.current_page||'—'],['Vault',p.vault_unlocked?'OPENED':'SEALED']].map(([k,v])=>`<div class="record"><small>${esc(k)}</small><strong>${esc(v)}</strong></div>`).join('')}</div><p class="quiet small">Completed days: ${esc((p.solved_days||[]).join(', ')||'none')}</p></section>`:'<div class="alert warning">Bella has not signed into her player account yet. Once she logs in, her progress will appear.</div>'}
 <section class="card"><h2>Emergency controls</h2><p class="quiet">You may enable Test Mode to rehearse now. The reset button deletes her play progress, notes and stamps from Supabase; personal browser notebook entries are stored separately on her device.</p><div class="actions"><button class="button secondary" data-action="${snapshot.test_mode?'test-off':'test-on'}">${snapshot.test_mode?'DISABLE TEST MODE':'ENABLE TEST MODE'}</button><button class="button danger" data-action="reset">RESET BELLA'S PROGRESS</button></div><div class="rule"></div><label for="manualDay">Emergency: mark one day completed</label><div class="entry-row"><select id="manualDay" class="field">${CASES.map(d=>`<option value="${d.id}">Day ${d.id}: ${esc(d.title)}</option>`).join('')}</select><button class="button secondary" data-action="complete-day">MARK COMPLETE</button></div></section>
 <section class="card"><h2>Send a handler transmission</h2><form id="adminNoteForm"><label for="noteText">Message to Agent Bunny</label><textarea class="field" id="noteText" name="note" rows="3" maxlength="500" required placeholder="Agent Bunny, a clue has surfaced..."></textarea><button type="submit" class="button primary spaced">SEND TRANSMISSION</button></form></section>
 <section class="card"><h2>Recent case activity</h2>${(snapshot.events||[]).slice(0,40).map(e=>`<div class="event"><span>${esc(e.event_type)} — ${esc(e.detail)}</span><small>${esc(stamp(e.created_at))}</small></div>`).join('')||'<p class="quiet">No activity yet.</p>'}</section>`,'ADMINISTRATOR');}
function prelude(){const now=Date.parse(snapshot.server_time||new Date().toISOString());const visible=PRELUDE.filter(v=>snapshot.test_mode||now>=Date.UTC(2026,10,v.day,0));const future=PRELUDE.length-visible.length;
 const last=visible.find(v=>v.day===29);shell(`<div class="prelude-hero"><div class="eyebrow">GALACTIC FEDERATION · PRE-MISSION</div><h1>THE COUNTDOWN <em>BEGINS.</em></h1><p>Ten intercepted bulletins from November 20 to November 29. No email required. Each transmission adds another piece of the mystery before the first door opens.</p><div class="prelude-stats">${visible.length} / 10 BULLETINS DECRYPTED <span>●</span> ${future?'NEXT TRANSMISSION PENDING':'ALL TRANSMISSIONS RECEIVED'}</div></div><div class="prelude-timeline">${PRELUDE.map((entry,i)=>{const unlocked=visible.includes(entry);return `<article class="prelude-entry ${unlocked?'readable':'pending'}"><div class="prelude-date">${esc(entry.date)}<span>${String(i+1).padStart(2,'0')}</span></div><div class="prelude-copy"><div class="eyebrow">${esc(entry.code)}</div><h2>${unlocked?esc(entry.title):'ENCRYPTED TRANSMISSION'}</h2>${unlocked?`<p>${esc(entry.body)}</p><div class="prelude-annotation">ARCHIVE FOOTNOTE // ${esc(entry.clue)}</div>`:'<p class="quiet">This message will be revealed on its scheduled date. Time restrictions are checked against the server.</p>'}${entry.day===29&&unlocked?`<div class="prelude-qr"><div data-qr="${esc(location.origin+location.pathname+'#/dossier/1')}"></div><a class="button secondary" href="#/dossier/1">ACTIVATION TRANSIT PASS ↗</a></div>`:''}</div></article>`;}).join('')}</div>`,'PRELUDE DISPATCH');}
function dossier(n){const d=dayCase(n);if(!d){shell('<section class="card">Unknown dossier.</section>');return;}if(!canPlay(n)){shell(locked(n));return;}const l=loreOf(n);const dt=gateStage(n);
 shell(`<section class="dossier-hero" style="--scene:${esc(l.color)}"><div class="dossier-noise"></div><div class="dossier-head"><span class="eyebrow">CLASSIFIED DOSSIER / ${esc(l.code)}</span><span class="access-chip">${solved(n)?'RECOVERED':'ACTIVE CASE'}</span></div><div class="dossier-symbol">${esc(l.icon)}</div><div class="dossier-lede"><span class="overline">SECTOR ${fmtDay(n)} · ${esc(l.sector)}</span><h1>${esc(d.title)}</h1><p>${esc(l.brief)}</p></div><div class="dossier-foot"><span>${esc(d.date.toUpperCase())} / 2026</span><span>${dt} OF 3 LOCKS RELEASED</span><span>HANDLER / WYATT</span></div></section>
 <div class="two-panel"><section class="card dossier-copy"><div class="section-label"><span>01 / PRIORITY ORDERS</span><span>AGENT BUNNY ONLY</span></div><h2>Assignment details</h2><p>${esc(d.story)}</p><blockquote>${esc(l.witness)}</blockquote><h3>Investigation objectives</h3><p>${esc(l.objective)}</p><div class="dossier-links"><a href="${roomUrl('dispatch',n)}">01 → Dispatch network</a><a href="${roomUrl('registry',n)}">02 → Personnel registry</a><a href="${roomUrl('surveillance',n)}">03 → Camera network</a><a href="${roomUrl('laboratory',n)}">04 → Laboratory</a></div></section>
 <section class="card log-card"><div class="section-label"><span>02 / RECOVERED TIMELINE</span><span>PARTIAL DECRYPT</span></div><h2>Forensic transcript</h2><div class="log-lines">${l.logs.map(([time,text],i)=>`<div class="log-line"><time>${esc(time)}</time><div><small>ENTRY ${String(i+1).padStart(2,'0')}</small><p>${esc(text)}</p></div></div>`).join('')}</div><div class="redacted-file"><span>HANDWRITTEN ANNOTATION</span><p>${esc(l.annotation)}</p></div></section></div>
 <section class="mission-tape"><div><div class="eyebrow">EXPERIMENT 626 / TRANSMISSION FRAGMENT</div><h2>Unlicensed agent interference</h2><p>“${esc(d.message)}”</p></div>${miniWave(n)}</section>
 <div class="dossier-bottom"><a class="button primary" href="${doorUrl(n)}">PROCEED TO THE SECURITY DOOR ↗</a><a class="button ghost" href="#/blackbox">SEARCH THE BLACK-BOX ARCHIVES</a></div>${roomNotebook(n)}`,'MISSION DOSSIER');}
function atlas(){const next=activeCase();shell(`<div class="page-heading"><span class="eyebrow">NAVIGATION / CLASSIFIED INFRASTRUCTURE</span><h1>THE <em>FACILITY.</em></h1><p>Every department knows a different piece of the truth. No single page has enough evidence to solve a door. Move between these rooms to verify names, dates, signals and calculations.</p></div>
 <section class="map-feature"><div class="atlas-map"><div class="map-grid">${facilityMap(next.id)}</div></div><div class="atlas-panel"><div class="section-label"><span>NETWORK BLUEPRINT</span><span class="live-led">● CONNECTED</span></div><h2>SECTOR ROUTING ACTIVE</h2><p>SELECT ANY NODE ON THE HOLOGRAPHIC MAP. Each one opens the corresponding department for your current mission.</p><div class="map-index">${areas.map(([s,label],i)=>`<a href="${roomUrl(s,next.id)}"><span>0${i+1}</span><strong>${esc(label)}</strong><b>↗</b></a>`).join('')}</div></div></section>
 <div class="section-label"><span>ADDITIONAL NODES</span><span>DISCOVERIES MAY CHANGE YOUR MAP</span></div><div class="feature-grid"><a href="#/dossier/${next.id}" class="feature-box"><span>◎</span><h3>Investigations</h3><p>Transcripts and objectives per day.</p><b>VIEW DOSSIER ↗</b></a><a href="#/blackbox" class="feature-box"><span>◷</span><h3>Black Box</h3><p>Bonus cross-department verification.</p><b>ENTER ARCHIVE ↗</b></a><a href="#/board" class="feature-box"><span>⌘</span><h3>Constellation Board</h3><p>Stamps from previously recovered cases.</p><b>CONNECT EVIDENCE ↗</b></a><a href="#/field-kit" class="feature-box"><span>⊞</span><h3>Forensic Tools</h3><p>Clock, cipher and numerical workbench.</p><b>OPEN TOOLKIT ↗</b></a></div>
 <section class="secret-hint"><span>ANOMALY DETECTED</span><p>Some paths are intentionally missing from this map. Look for route markers in the Personnel Registry, incident notes, and recovered files. Type discovered paths into the address bar after the # symbol.</p></section>`,'HOLOGRAPHIC ATLAS');}
const SUSPECTS=[{name:'EXPERIMENT 626',designation:'SUBJECT 626',risk:'CHAOTIC',initial:'626',bio:'Primary suspect. Small, blue, creative with the truth, and unusually fond of messing with official forms. Can be helpful in a spectacularly inconvenient way.',link:'The official theft report. Every improvised message contains at least one useful clue.'},{name:'AGENT WYATT',designation:'COMMAND HANDLER',risk:'AUTHORIZED',initial:'W',bio:'Your handler. Knows the facility unusually well, leaves personal fingerprints in otherwise serious documents, and has strong opinions about paperwork.',link:'Connected to the trusted callsigns in Personnel Registry.'},{name:'UNKNOWN INFORMANT',designation:'UNVERIFIED SOURCE',risk:'UNCONFIRMED',initial:'?',bio:'Sends fragments across unauthorized frequencies. Often seems to know which records matter before anyone has examined them.',link:'Reappears in the late-game evidence and the OHANA annex.'},{name:'AGENT BUNNY',designation:'PRIMARY INVESTIGATOR',risk:'ESSENTIAL',initial:'B',bio:'You. Selected to retrieve an object no one has ever been able to describe clearly. Your assignment spans fifteen separate investigations.',link:'Personnel Registry cleared your entry; your own history may become evidence.'}];
function suspects(){shell(`<div class="page-heading"><span class="eyebrow">PERSONNEL / EXTERNAL SUBJECTS</span><h1>SUSPECT <em>DATABASE.</em></h1><p>Four individuals. A conspicuously missing description of the artifact. Every person in this file has something to do with the investigation.</p></div><div class="suspect-grid">${SUSPECTS.map((s,i)=>`<article class="suspect-card"><div class="suspect-portrait portrait-${i}"><span>${esc(s.initial)}</span><div class="reticle"></div></div><div class="suspect-details"><div class="eyebrow">${esc(s.designation)} · ${esc(s.risk)}</div><h2>${esc(s.name)}</h2><p>${esc(s.bio)}</p><div class="suspect-link">RELATED EVIDENCE <span>${esc(s.link)}</span></div></div></article>`).join('')}</div>`,'SUSPECT REGISTRY');}
function transmissions(){const n=activeCase().id;const visible=CASES.filter(d=>canPlay(d.id));shell(`<div class="page-heading"><span class="eyebrow">DISTRESS FREQUENCY / CHANNEL 626</span><h1>UNAUTHORIZED <em>TRANSMISSIONS.</em></h1><p>Experiment 626 and the Unknown Informant are both broadcasting to the same channel. The noise is obnoxious. Occasionally, the noise is useful.</p></div><section class="signal-hero"><div><span class="eyebrow">LIVE CHANNEL 06.26</span><h2>INTERCEPT ACTIVE</h2><p>Click a message to cross-reference its case. Some words only make sense after the door opens.</p></div>${miniWave(4)}</section>${notices()}<div class="message-stack">${visible.map(d=>`<a class="message-card" href="#/dossier/${d.id}"><span class="message-frequency">CH-${fmtDay(d.id)} <span>626</span></span><div><div class="eyebrow">EXPERIMENT 626 / ${esc(d.date)}</div><h3>“${esc(d.message)}”</h3><p>${solved(d.id)?esc(d.emotion):'PROVENANCE UNVERIFIED · CONTEXT PARTIALLY REDACTED'}</p></div><span class="message-arrow">↗</span></a>`).join('')}</div>`,'RADIO TRANSCEIVER');}
function fieldkit(){const next=activeCase();const cams=next.laboratory.calibration;const out=String(cipherPhrase).toUpperCase().replace(/[A-Z]/g,c=>String.fromCharCode((c.charCodeAt(0)-65+cipherShift+26)%26+65));shell(`<div class="page-heading"><span class="eyebrow">ANALYTICAL SYSTEMS / AGENT-ACCESSIBLE</span><h1>FORENSIC <em>WORKBENCH.</em></h1><p>No programming necessary. These physical-style instruments let you test the evidence. They do not reveal private security answers.</p></div><div class="work-grid"><section class="card tool-card"><span class="tool-number">01 / TEMPORAL RECONSTRUCTION</span><h2>Camera clock correction</h2><p>Surveillance frames show raw minutes. Pick a camera, enter its recorded minute and add the offset from Laboratory.</p><form id="clockForm"><label>Camera</label><select class="field" name="cam">${cams.map(c=>`<option value="${esc(c.camera)}">${esc(c.camera)}</option>`).join('')}</select><label>Recorded minute, 0–59</label><input class="field" name="minute" type="number" min="0" max="59" value="15" required><button class="button secondary" type="submit">CALCULATE ACTUAL TIME ↗</button></form><div class="tool-result" id="clockResult">Choose camera and time. Read its calibration in Laboratory first.</div></section>
<section class="card tool-card"><span class="tool-number">02 / ALPHABET DISCOVERY</span><h2>Rotating cipher wheel</h2><p>Shift any letters forward or backward and watch the output change. Useful for nontechnical cipher side trails.</p><label>Intercept text</label><input class="field" data-cipher-text value="${esc(cipherPhrase)}" maxlength="80"><label>Shift <span id="cipherShiftLabel">${cipherShift}</span></label><input type="range" min="-13" max="13" value="${cipherShift}" data-cipher-shift><div class="tool-result mono" id="cipherResult">${esc(out)}</div></section>
<section class="card tool-card"><span class="tool-number">03 / CALIBRATION MATRIX</span><h2>Specimen arithmetic desk</h2><p>Use scratch calculations for Laboratory batches. Decide the right operation from the door instructions.</p><form id="mathForm"><div class="form-pair"><label>Reading A<input class="field" name="a" type="number" value="12" required></label><label>Reading B<input class="field" name="b" type="number" value="7" required></label></div><select class="field" name="mode"><option value="add">A + B</option><option value="sub">A − B</option><option value="mul">A × B</option></select><button type="submit" class="button secondary">PROCESS READINGS ↗</button></form><div class="tool-result" id="mathResult">AWAITING DATA</div></section>
<section class="card tool-card"><span class="tool-number">04 / FIELD NOTEBOOK</span><h2>Independent investigation notes</h2><p>Your notes are saved on this device, even if you move between departments. They are not copied to your handler.</p>${roomNotebook(next.id)}<a class="text-cta" href="#/board">OPEN THE EVIDENCE BOARD ↗</a></section></div>`,'FORENSIC TOOLKIT');}
function bonusAnswer(d){const batch=String(d.dispatch.batch).match(/\d+/)?.[0]||'0';const c1=d.laboratory.calibration.find(x=>x.camera==='C1');return `${batch.at(-1)}${d.registry.clearance}${Math.abs(c1?.offset||0)}`;}
function blackbox(){const items=CASES.filter(d=>canPlay(d.id));const n=Number((new URLSearchParams(location.hash.split('?')[1]||'')).get('day'))||activeCase().id;const d=dayCase(n);if(!d||!canPlay(n)){shell(locked(n));return;}const l=loreOf(n),checked=bonusChecked.has(n);
 shell(`<div class="blackbox-hero"><div class="blackbox-glow"></div><div class="eyebrow">UNLISTED SYSTEM / ARCHIVE DISCREPANCY</div><h1>THE <em>BLACK BOX.</em></h1><p>There is one extra document hiding behind every case. The Federation labeled these files nonessential. The Unknown Informant disagrees.</p><div class="blackbox-indicator"><span class="status-dot"></span> ${bonusChecked.size} / 15 PRIVATE ECHOS DECRYPTED</div></div><div class="two-panel"><section class="card"><div class="section-label"><span>SELECT SIGNAL SOURCE</span><span>01–15</span></div><div class="blackbox-day-grid">${items.map(c=>`<a href="#/blackbox?day=${c.id}" class="blackbox-day ${c.id===n?'selected':''} ${bonusChecked.has(c.id)?'unlocked':''}">${fmtDay(c.id)}${bonusChecked.has(c.id)?'<span>✓</span>':''}</a>`).join('')}</div><h2>Black Box ${fmtDay(n)}</h2><p>${esc(l.signal)} // Incident chain: ${esc(l.code)}</p><div class="artifact-code">CROSS-DEPARTMENT AUTHENTICATION<br><span>01</span> Approved batch: use its FINAL DIGIT (Dispatch)<br><span>02</span> Confirmed clearance LEVEL (Personnel)<br><span>03</span> ABSOLUTE C1 clock correction (Laboratory)<br><small>Write those three values side-by-side, without spaces.</small></div>${checked?`<div class="alert good">INTELLIGENCE ALREADY DECRYPTED ON THIS DEVICE</div>`:`<form id="blackboxForm" data-day="${n}"><label for="blackboxGuess">THREE-PART INTELLIGENCE STRING</label><div class="entry-row"><input class="field" name="guess" id="blackboxGuess" maxlength="12" autocomplete="off" required placeholder="_ _ _"><button class="button primary" type="submit">DECRYPT ↗</button></div></form>`}</section><section class="card blackbox-reward"><span class="eyebrow">CONCEALED SECONDARY RECORD</span>${checked?`<div class="reward-emblem">✦</div><h2>THE ECHO IS YOURS.</h2><blockquote>${esc(l.blackbox)}</blockquote><p>${esc(l.witness)}</p>`:`<div class="reward-emblem muted">◈</div><h2>CONTENTS ENCRYPTED</h2><p>Match the paper trail from three different rooms. Every daily Black Box is optional, but each adds something the official reports left out.</p>`}<div class="note-footer">LOCAL ONLY / BONUS DECRYPTION / DOES NOT BYPASS SECURITY DOORS</div></section></div>`,'UNLISTED BLACK BOX');}

function render(){if(!snapshot){loginView();return;}if(snapshot.role==='admin'){admin();return;}
 const path=currentRoute();let m;
 if(path==='/'||path==='/dashboard'){home();return;}
 if(path==='/reports'){reports();return;}
 if(path==='/prelude'){prelude();return;}
 if(path==='/atlas'){atlas();return;}
 if(path==='/suspects'){suspects();return;}
 if(path==='/transmissions'){transmissions();return;}
 if(path==='/field-kit'){fieldkit();return;}
 if(path.startsWith('/blackbox')){blackbox();return;}
 if((m=path.match(/^\/dossier\/(\d{1,2})$/))){dossier(Number(m[1]));return;}
 if(path==='/doors'){allDoors();return;}
 if((m=path.match(/^\/door\/(\d{1,2})$/))){door(Number(m[1]));return;}
 if((m=path.match(/^\/facility\/(dispatch|surveillance|laboratory|registry)\/(\d{1,2})$/))){facility(m[1],Number(m[2]));return;}
 if(path==='/board'){board();return;}
 if(path==='/archive'){archive();return;}
 if(path==='/classified'||path==='/archive/ohana'){annex(path);return;}
 if(path==='/vault'||path==='/vault/final'){vault();return;}
 if(path==='/0914-b'){secret();if(lastSecretData)secretContents(lastSecretData);return;}
 // Upgrade compatibility: old /reports/1 URLs now point at the new door.
 if((m=path.match(/^\/reports\/(\d{1,2})$/))){navigate('/door/'+m[1]);return;}
 navigate('/dashboard');
}
async function submitLogin(form){selectedRole=form.querySelector('input[name="role"]:checked')?.value||'player';const pwd=form.elements.password.value;const email=selectedRole==='admin'?cfg.adminEmail:cfg.playerEmail;
 if(!email||!pwd)throw new Error('Choose a role and enter its password.');
 const {error}=await client.auth.signInWithPassword({email,password:pwd});
 if(error)throw new Error('Incorrect password or missing Supabase user. Check Authentication → Users.');
 await refresh(false);if(snapshot.role!==selectedRole){await signOut();throw new Error('This password does not grant the selected role. Check Supabase role assignments.');}
 if(selectedRole==='player')await activity('login');navigate(selectedRole==='admin'?'/admin':'/dashboard');await refresh();}
async function onSubmit(form){if(form.id==='loginForm')return submitLogin(form);
 if(form.id==='blackboxForm'){const n=Number(form.dataset.day),correct=bonusAnswer(dayCase(n));const got=form.elements.guess.value.trim().toUpperCase();if(got!==correct){setFlash('Black Box authentication failed. Check all three source rooms.','bad');render();}else{bonusChecked.add(n);try{localStorage.setItem('ohana626-blackbox-'+n,'1');}catch{}setFlash('SECONDARY RECORD DECRYPTED.');render();}return;}
 if(form.id==='clockForm'){const camera=form.elements.cam.value;const min=Number(form.elements.minute.value);const off=activeCase().laboratory.calibration.find(c=>c.camera===camera)?.offset||0;const actual=(min+off+60)%60;const el=document.getElementById('clockResult');if(el)el.textContent='ACTUAL MINUTE: '+String(actual).padStart(2,'0')+'  | OFFSET '+(off>=0?'+':'')+off+' — Verify the correct order across all frames.';return;}
 if(form.id==='mathForm'){const a=Number(form.elements.a.value),b=Number(form.elements.b.value),mode=form.elements.mode.value;const r=mode==='add'?a+b:mode==='sub'?a-b:a*b;const el=document.getElementById('mathResult');if(el)el.textContent='CALCULATED OUTPUT: '+r;return;}
 if(form.id==='doorForm'){
  const d=Number(form.dataset.day),g=Number(form.dataset.gate);
  const result=await rpc('ohana_door',{p_day:d,p_gate:g,p_guess:form.elements.guess.value});
  setFlash(result.correct?(result.day_complete?`All three bolts released! Evidence E-${fmtDay(d)} recovered.`:`Bolt ${g} opened. Continue through the next department lock.`):`Code rejected. Failed attempt ${result.attempts||'recorded'}.`,result.correct?'good':'bad');await refresh();return;
 }
 if(form.id==='vaultForm'){
  const r=await rpc('ohana_vault',{p_key:form.elements.meta.value});if(r.ok){setFlash('FINAL VAULT UNSEALED.');await refresh();vaultContents(r.content);return;}setFlash(r.message||'Invalid meta key.','bad');await refresh();return;
 }
 if(form.id==='secretForm'){
  const r=await rpc('ohana_secret',{p_password:form.elements.secretpass.value});if(r.ok){setFlash('ARCHIVED FILE DECRYPTED.');await refresh();secretContents(r.content);return;}setFlash(r.message||'Incorrect archive password.','bad');await refresh();return;
 }
 if(form.id==='adminNoteForm'){await rpc('ohana_admin',{p_action:'note',p_message:form.elements.note.value});setFlash('Transmission delivered to Agent Bunny.');await refresh();}
}
async function onAction(btn){const action=btn.dataset.action;
 if(action==='logout'){await signOut();return;}
 if(action==='sound'){ambientSound=!ambientSound;try{const a=new (window.AudioContext||window.webkitAudioContext)(),o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.setValueAtTime(440,a.currentTime);o.frequency.exponentialRampToValueAtTime(660,a.currentTime+.16);g.gain.setValueAtTime(.025,a.currentTime);g.gain.exponentialRampToValueAtTime(.0001,a.currentTime+.2);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+.2);}catch{}render();return;}
 if(action==='enhance'){const d=Number(btn.dataset.day);if(enhanced.has(d))enhanced.delete(d);else enhanced.add(d);render();return;}
 if(action==='hint'){
  const d=Number(btn.dataset.day),tier=Number(btn.dataset.tier);
  const result=await rpc('ohana_hint',{p_day:d,p_tier:tier});
  let existing=cachedHints.get(d)||'';
  if(!existing.includes(`data-hint-tier="${tier}"`))existing+=`<div data-hint-tier="${tier}" class="hint"><strong>Level ${tier}:</strong> ${esc(result.hint)}</div>`;
  cachedHints.set(d,existing);await refresh();return;
 }
 if(action==='open-vault'){const result=await rpc('ohana_vault',{p_key:''});if(result.ok)vaultContents(result.content);return;}
 if(action==='reset'&&!confirm('Reset ALL Bella progress, hints, door bolts and vault status in Supabase? This cannot be undone.'))return;
 if(action==='test-on'&&!confirm('Enable Test Mode? All fifteen doors will be accessible ahead of schedule once the prior day is solved.'))return;
 if(action==='test-off'&&!confirm('Disable Test Mode and restore scheduled date locks?'))return;
 if(action==='complete-day'&&!confirm('Manually mark this case recovered for Bella?'))return;
 const method=({reset:'reset','test-on':'test_on','test-off':'test_off','complete-day':'complete'})[action];if(!method)return;
 const args={p_action:method};if(action==='complete-day')args.p_day=Number(document.getElementById('manualDay').value);
 await rpc('ohana_admin',args);setFlash(`Administrator action completed: ${method.replaceAll('_',' ')}.`);await refresh();
}
root.addEventListener('submit',async e=>{
 const form=e.target.closest('form');if(!form)return;e.preventDefault();if(busy)return;busy=true;
 const b=form.querySelector('[type="submit"]');if(b)b.disabled=true;
 try{await onSubmit(form);}catch(error){setFlash(error.message,'bad');if(snapshot)render();else loginView(error.message);}
 finally{busy=false;if(b?.isConnected)b.disabled=false;}
});
root.addEventListener('click',async e=>{
 const btn=e.target.closest('[data-action]');if(!btn||busy)return;busy=true;btn.disabled=true;
 try{await onAction(btn);}catch(error){setFlash(error.message,'bad');render();}finally{busy=false;if(btn.isConnected)btn.disabled=false;}
});
root.addEventListener('input',e=>{
 if(e.target.matches('[data-cipher-text],[data-cipher-shift]')){const src=document.querySelector('[data-cipher-text]'),range=document.querySelector('[data-cipher-shift]');cipherPhrase=src?.value||'';cipherShift=Number(range?.value||0);const label=document.getElementById('cipherShiftLabel');if(label)label.textContent=cipherShift;const o=document.getElementById('cipherResult');if(o)o.textContent=cipherPhrase.toUpperCase().replace(/[A-Z]/g,c=>String.fromCharCode((c.charCodeAt(0)-65+cipherShift+26)%26+65));return;}
 if(!e.target.matches('[data-note]'))return;
 try{localStorage.setItem('ohana626-notes-'+e.target.dataset.note,e.target.value);const status=e.target.closest('.notebook')?.querySelector('[data-note-status]');if(status)status.textContent='Notes saved on this device ✓';}catch{}
});
root.addEventListener('change',e=>{if(e.target.name==='role')selectedRole=e.target.value;});
window.addEventListener('hashchange',()=>{if(snapshot){render();activity(currentRoute());}});
async function boot(){
 if(!cfg.url?.startsWith('https://')||!cfg.publishableKey||cfg.publishableKey.includes('PASTE_')){loginView('Setup required: edit config.js with your Supabase Project URL and publishable key.');return;}
 if(!window.supabase?.createClient){loginView('Could not load Supabase. Check your internet connection, then refresh.');return;}
 try{
  client=window.supabase.createClient(cfg.url,cfg.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:false}});
  const {data,error}=await client.auth.getSession();if(error)throw error;
  if(data.session){try{await refresh(false);}catch{await client.auth.signOut();snapshot=null;}}
  render();if(snapshot?.role==='player')activity('login');
  setInterval(async()=>{
   if(!snapshot||busy||document.hidden)return;
   const active=document.activeElement;if(active&&['INPUT','TEXTAREA','SELECT'].includes(active.tagName))return;
   try{await refresh();}catch(e){console.warn(e.message);}
  },12000);
  setInterval(()=>{if(snapshot?.role==='player'&&!document.hidden)activity(currentRoute());},30000);
 }catch(error){loginView('Connection failed: '+error.message);}
}
boot();
